function allItins() { return A.ITINS.concat(S.newItins); }
function stopInfo(s) { if (s.kind === 'event') { const e = A.allEvents().find(x => x.id === s.ref); return { title: s.title || e.title, sub: e.venue, img: e.img, tone: e.tone, emoji: e.emoji, href: '/event/' + e.id, lat: e.lat, lng: e.lng }; } if (s.kind === 'biz') { const b = A.allBiz().find(x => x.id === s.ref); return { title: s.title || b.name, sub: `${b.name} · ${b.cat}`, img: b.img, href: '/business/' + b.id, lat: b.lat, lng: b.lng }; } const p = A.byId(A.PLACES, s.ref); return { title: s.title || p.name, sub: p.type + (p.guide ? ` · ghid audio · ${p.guide.length} puncte` : ''), img: p.img, tone: p.tone, emoji: '📍', href: '/place/' + p.id, lat: p.lat, lng: p.lng, guide: !!p.guide }; }
function itinDone(it) { return S.itinDone[it.id] || it.done || []; }
