ACT.cityAct = a => { UI.tmp.cityAct = a; render(); };
ACT.validate = a => { const [code, status] = a.split(':'); const r = A.allRegs().find(x => x.code === code); const act = A.allActions().find(x => x.id === r.action); S.validations[code] = { status, by: S.user ? S.user.name : 'Primăria', when: A.NOW }; if (status === 'CONFIRMED' && r.who === (S.user && S.role === 'local' ? S.user.name : 'Ana P.')) S.points += act.pts; S.scans.push({ kind: 'action', code, who: r.who, by: S.user ? S.user.name : 'Primăria', at: A.NOW, status, pts: status === 'CONFIRMED' ? act.pts : 0 }); save(); toast(status === 'CONFIRMED' ? `${r.who} · confirmat · +${act.pts} puncte` : `${r.who} · respins`, status === 'CONFIRMED' ? 'check_circle' : 'cancel'); render(); };
ACT.valOpen = () => sheet(`<div class="shd"><h2>Validează un cod</h2><button class="link" data-act="closeSheet">Închide</button></div><div class="scanner" style="height:220px"><div class="fr"><i></i></div><div class="ln"></div><div class="cap">Îndreaptă camera spre codul QR al clientului</div></div><div class="row" style="gap:8px;margin-top:12px"><input class="field grow" placeholder="sau introdu codul: AX-O1-…" data-bind="valCode" value="${esc(UI.tmp.valCode || '')}"><button class="btn sm" data-act="valCheck">Validează</button></div><button class="btn sec" style="margin-top:10px" data-act="scanSim" data-arg="biz">Simulează scanarea</button>${UI.tmp.valRes ? `<div class="note ${UI.tmp.valRes.ok ? 'green' : 'err'}" style="margin-top:12px">${ms(UI.tmp.valRes.ok ? 'check_circle' : 'error', 's')}<span>${esc(UI.tmp.valRes.msg)}</span></div>` : ''}`);
ACT.valCheck = () => { const code = (UI.tmp.valCode || '').trim().toUpperCase(); const c = S.claims.find(x => x.code === code); if (!c) { UI.tmp.valRes = { ok: false, msg: 'Cod necunoscut. Verifică literele sau cere clientului să îl arate din nou.' }; } else if (c.used) UI.tmp.valRes = { ok: false, msg: 'Codul a fost deja folosit.' }; else { c.used = true; S.scans.push({ kind: 'offer', code, at: A.NOW }); save(); const o = A.allOffers().find(x => x.id === c.offerId); UI.tmp.valRes = { ok: true, msg: `Cod valid · ${o.title}${c.points ? ` · plătit cu ${c.points} puncte` : ''}. Marcat folosit.` }; } ACT.valOpen(); };
ACT.scanSim = who => { if (who === 'biz') { const c = S.claims.find(x => !x.used); if (c) { UI.tmp.valCode = c.code; ACT.valCheck(); } else { UI.tmp.valRes = { ok: false, msg: 'Niciun cod activ în acest browser. Revendică o ofertă din aplicație (rol Localnic) și revino.' }; ACT.valOpen(); } return; } const cur = UI.tmp.cityAct || A.pubActions()[0].id; const r = A.allRegs().find(x => x.action === cur && x.status !== 'CONFIRMED'); if (r) ACT.validate(r.code + ':CONFIRMED'); else toast('Toți participanții sunt confirmați.'); };

/* ---------- Voluntar ---------- */
function vol() { return A.allVols().find(v => v.id === S.volId) || A.allVols()[0]; }
route('/vol/login', () => ({ nav: false, body: `<div class="hd back" style="margin-top:4px">${backBtn()}</div><span class="ms" style="font-size:44px">badge</span><h1 style="margin-top:12px">Conectare voluntar</h1><p class="mut" style="margin-top:10px;font-size:15px">Introdu codul de 6 cifre primit prin SMS când Primăria ți-a creat contul.</p>
  <label class="lab" style="margin-top:22px">Cod de acces</label><input class="field mono" inputmode="numeric" maxlength="6" placeholder="••••••" style="font-size:24px;letter-spacing:.3em;text-align:center;height:64px" data-bind="volCode" data-enter="volLogin" value="${esc(UI.tmp.volCode || '')}">
  ${UI.tmp.volErr ? `<div class="note err" style="margin-top:10px">${ms('error', 's')}<span>${esc(UI.tmp.volErr)}</span></div>` : ''}
  <button class="btn" style="margin-top:14px" data-act="volLogin">Conectează-te</button>
  <p class="mut" style="font-size:13px;margin-top:22px">Prototip · conturi create în admin (atinge ca să intri):</p><div class="row" style="flex-wrap:wrap;gap:8px;margin-top:8px">${A.allVols().map(v => `<button class="chip sm" data-act="volPick" data-arg="${v.code}">${v.code} · ${esc(v.name)}</button>`).join('')}</div>` }));
ACT.volPick = c => { UI.tmp.volCode = c; ACT.volLogin(); };
ACT.volLogin = () => { const c = (UI.tmp.volCode || '').trim(); const v = A.allVols().find(x => x.code === c); if (!v) { UI.tmp.volErr = 'Cod greșit. Verifică SMS-ul sau întreabă coordonatorul.'; render(); return; } if (v.status === 'SUSPENDED') { UI.tmp.volErr = 'Contul este suspendat. Contactează coordonatorul.'; render(); return; } S.role = 'volunteer'; S.volId = v.id; S.user = { name: v.name, email: v.email }; UI.tmp.volErr = ''; save(); toast(`Bun venit, ${v.name.split(' ')[0]}! Vezi doar acțiunile tale.`); go('/vol/actions', true); };
function volActionState(a) { const unlocked = S.unlocked[a.id] || a.date === A.TODAY; const regs = A.allRegs().filter(r => r.action === a.id); const mine = regs.filter(r => r.status === 'CONFIRMED').length; const total = regs.length; return { unlocked, done: total > 0 && mine === total, mine, total }; }
route('/vol/actions', () => {
  const v = vol(); const acts = A.allActions().filter(a => v.actions.includes(a.id)); const scanned = S.scans.filter(s => s.kind === 'action' && s.by === v.name).length; const toScan = acts.reduce((s, a) => s + A.allRegs().filter(r => r.action === a.id && r.status !== 'CONFIRMED').length, 0);
  return { body: `<div class="hd" style="align-items:center"><h1>Acțiunile tale</h1>${avatarBtn()}</div>
    <div class="card pad" style="background:var(--ink);color:var(--bg);border:none"><div class="row" style="gap:12px"><span class="av" style="background:var(--bg);color:var(--ink);border:none">${A.initials(v.name)}</span><div class="grow"><b style="font-size:17px">${esc(v.name)}</b><br><span style="opacity:.75;font-size:13.5px">Coordonator: ${esc(v.coord)}</span></div><span class="badge" style="background:var(--acc);color:#fff;font-weight:700">Voluntar</span></div><div class="stat3" style="margin-top:14px">${[[acts.length, 'acțiuni alocate'], [scanned + v.scans, 'scanați de tine'], [toScan, 'de scanat']].map(([n, l]) => `<div style="background:rgba(255,255,255,.1);border:none"><b style="color:inherit">${n}</b><span style="color:inherit;opacity:.75">${l}</span></div>`).join('')}</div><p style="opacity:.6;font-size:12.5px;margin-top:12px">Cont creat de Primăria Arad${v.oneTime ? ' · de unică folosință' : ''}</p></div>
    <h2 style="margin:20px 0 10px">Alocate ție</h2>
    ${acts.map(a => { const st = volActionState(a); const d = A.dayParts(a.date); return `<div class="locked" style="margin-bottom:14px"><div class="card pad"><div class="row" style="gap:12px;align-items:flex-start"><div class="datechip" style="position:static;flex:none"><span>${d.dow}</span><b>${d.n}</b><span>${d.mon}</span></div><div class="grow"><b style="font-size:16px;line-height:1.25;display:block">${esc(a.title)}</b><span class="mut" style="font-size:13px">${a.time}–${a.end} · ${esc(a.place)}</span><div class="row" style="gap:8px;margin-top:8px"><span class="badge green" style="font-size:12px">${st.mine}/${st.total} confirmați</span></div></div></div><div class="bar" style="background:var(--soft);height:6px;margin:12px 0"><i style="width:${st.total ? Math.round(st.mine / st.total * 100) : 0}%;background:var(--green)"></i></div><div class="row" style="gap:8px"><button class="btn sm grow" data-act="volScanFor" data-arg="${a.id}">${ms('qr_code_scanner', 's')} Scanează aici</button><button class="btn sm sec" style="width:auto" data-go="/map?to=act:${a.id}">${ms('directions', 's')} Indicații</button></div></div>
      ${!st.unlocked ? `<div class="veil"><span class="lk">${ms('lock')}</span><b style="font-size:17px">Se deschide ${A.dayLabel(a.date).toLowerCase()}</b><span class="mut" style="font-size:13.5px">Poți scana de la ${(parseInt(a.time) - 1).toString().padStart(2, '0')}:30, cu 30 de minute înainte de start · peste ${Math.max(1, (new Date(a.date) - new Date(A.TODAY)) / 864e5)} zile</span><button class="link mut" style="font-size:13px;margin-top:4px" data-act="unlock" data-arg="${a.id}">Prototip: deblochează acum</button></div>` : st.done ? `<div class="donecard"><span class="lk">${ms('check')}</span><b style="font-size:17px">Gata! Toți au fost confirmați</b><span style="font-size:13.5px">${st.mine}/${st.total} · mulțumim, ${esc(v.name.split(' ')[0])}</span></div>` : ''}</div>`; }).join('')}` };
});
ACT.unlock = id => { S.unlocked[id] = true; save(); toast('Deblocat pentru demo.'); render(); };
ACT.volScanFor = id => { UI.tmp.volAct = id; go('/vol/scan'); };
route('/vol/scan', () => {
  const v = vol(); const acts = A.allActions().filter(a => v.actions.includes(a.id)); const cur = acts.find(a => a.id === UI.tmp.volAct) || acts.find(a => volActionState(a).unlocked) || acts[0]; const st = volActionState(cur); const recent = S.scans.filter(s => s.kind === 'action' && s.by === v.name).slice(-4).reverse(); const res = UI.tmp.scanRes;
  return { body: `<div class="hd" style="align-items:center"><h1>Scanează</h1>${avatarBtn()}</div>
    <div class="chips" style="margin-bottom:12px">${acts.map(a => `<button class="chip sm ${a.id === cur.id ? 'on' : ''}" data-act="volScanFor" data-arg="${a.id}">${a.emoji} ${esc(a.title.split(' ').slice(0, 3).join(' '))}</button>`).join('')}</div>
    <div class="scanner"><div class="fr"><i></i></div>${st.unlocked ? '<div class="ln"></div>' : ''}<div class="cap">Îndreaptă camera spre codul QR al participantului</div>${!st.unlocked ? `<div class="lock">${ms('lock')}<b>Scanarea se deschide ${A.dayLabel(cur.date).toLowerCase()}</b><span style="font-size:13px;opacity:.85">cu 30 de minute înainte de start</span><button class="link" style="font-size:13px" data-act="unlock" data-arg="${cur.id}">Prototip: deblochează acum</button></div>` : ''}</div>
    <div class="row" style="gap:8px;margin-top:12px"><button class="btn grow" data-act="volScanSim" ${st.unlocked ? '' : 'disabled'}>Simulează scanarea</button><button class="btn sec" style="width:auto;padding:0 16px" data-act="volCodeSheet" ${st.unlocked ? '' : 'disabled'}>Introdu codul</button></div>
    ${res ? `<div class="note ${res.kind === 'ok' ? 'green' : res.kind === 'dup' ? '' : 'err'}" style="margin-top:12px;padding:14px">${ms(res.kind === 'ok' ? 'check_circle' : res.kind === 'dup' ? 'info' : 'error')}<span><b>${esc(res.title)}</b><br>${esc(res.sub)}</span></div>` : ''}
    <h3 style="margin:20px 0 8px">Scanări recente</h3>${recent.length ? recent.map(s => `<div class="kv">${ms(s.status === 'CONFIRMED' ? 'check_circle' : 'cancel', 's')}<div class="grow"><div class="t">${esc(s.who)}</div><div class="s mono">${s.code}</div></div><span class="badge ${s.status === 'CONFIRMED' ? 'green' : ''}" style="font-size:12px">${s.status === 'CONFIRMED' ? '+' + s.pts : 'respins'} · ${s.at}</span></div>`).join('') : '<p class="mut" style="font-size:14px">Nicio scanare încă.</p>'}` };
});
ACT.volScanSim = () => { const v = vol(); const acts = A.allActions().filter(a => v.actions.includes(a.id)); const cur = acts.find(a => a.id === UI.tmp.volAct) || acts.find(a => volActionState(a).unlocked) || acts[0]; const r = A.allRegs().find(x => x.action === cur.id && x.status !== 'CONFIRMED'); if (!r) { UI.tmp.scanRes = { kind: 'dup', title: 'Toți participanții sunt confirmați', sub: `${cur.title}: nimic de scanat.` }; render(); return; } S.validations[r.code] = { status: 'CONFIRMED', by: v.name, when: A.NOW }; S.scans.push({ kind: 'action', code: r.code, who: r.who, by: v.name, at: A.NOW, status: 'CONFIRMED', pts: cur.pts }); if (r.who === 'Ana P.') S.points += cur.pts; save(); UI.tmp.scanRes = { kind: 'ok', title: `${r.who} · confirmat`, sub: `${r.code} · +${cur.pts} puncte acordate · acum` }; render(); };
ACT.volCodeSheet = () => sheet(`<div class="shd"><h2>Introdu codul</h2><button class="link" data-act="closeSheet">Închide</button></div><input class="field mono" placeholder="AX-C1-…" data-bind="volManual" value="${esc(UI.tmp.volManual || '')}"><button class="btn" style="margin-top:12px" data-act="volManualGo">Confirmă participantul</button>`);
ACT.volManualGo = () => { const code = (UI.tmp.volManual || '').trim().toUpperCase(); const r = A.allRegs().find(x => x.code === code); closeSheet(); if (!r) { UI.tmp.scanRes = { kind: 'err', title: 'Cod necunoscut', sub: 'Verifică literele sau cere participantului să arate din nou codul.' }; } else if (r.status === 'CONFIRMED') UI.tmp.scanRes = { kind: 'dup', title: `${r.who} · deja scanat`, sub: `Confirmat de ${r.by || 'Primărie'} la ${r.when || ''}.` }; else { const v = vol(); const a = A.allActions().find(x => x.id === r.action); S.validations[code] = { status: 'CONFIRMED', by: v.name, when: A.NOW }; S.scans.push({ kind: 'action', code, who: r.who, by: v.name, at: A.NOW, status: 'CONFIRMED', pts: a.pts }); if (r.who === 'Ana P.') S.points += a.pts; save(); UI.tmp.scanRes = { kind: 'ok', title: `${r.who} · confirmat`, sub: `${code} · +${a.pts} puncte acordate · acum` }; } render(); };
route('/vol/messages', () => {
  const v = vol(); const msgs = (A.MSGS[v.id] || []).concat(S.msgs[v.id] || []);
  return { body: `<div class="hd" style="align-items:center"><div><h1>Mesaje</h1><p class="mut" style="font-size:14px;margin-top:4px">Conversație cu ${esc(v.coord)}, coordonatorul tău</p></div>${avatarBtn()}</div>
    <div class="col" style="gap:10px;padding-bottom:70px">${msgs.map(m => `<div class="bubble ${m.from === 'vol' ? 'me' : 'bot'}">${esc(m.text)}</div><span class="mut" style="font-size:11.5px;${m.from === 'vol' ? 'align-self:flex-end' : ''}">${m.from === 'vol' ? 'tu' : esc(v.coord)} · ${m.at}</span>`).join('')}
    <div class="row" style="flex-wrap:wrap;gap:8px;margin-top:6px">${A.QUICK.map(q => `<button class="chip sm" data-act="volSend" data-arg="${esc(q)}">${esc(q)}</button>`).join('')}</div></div>`,
    fixed: `<div class="composer"><input class="field grow" placeholder="Scrie coordonatorului…" data-bind="volMsg" data-enter="volSendInput" value="${esc(UI.tmp.volMsg || '')}"><button class="send" data-act="volSendInput">${ms('arrow_upward')}</button></div>`, after: () => { const el = document.getElementById('view'); if (el) el.scrollTop = el.scrollHeight; } };
});
ACT.volSendInput = () => { const t = (UI.tmp.volMsg || '').trim(); if (!t) return; UI.tmp.volMsg = ''; ACT.volSend(t); };
ACT.volSend = t => { const v = vol(); (S.msgs[v.id] = S.msgs[v.id] || []).push({ from: 'vol', text: t, at: 'azi, ' + A.NOW }); save(); render(); };
